import artifactsJson from './artifacts.json'

interface PlatformArtifact {
  file: string
  /** Set when the file is published elsewhere (the Windows release asset). */
  url?: string
  /** True when the site itself serves the file from /downloads. */
  selfHosted?: boolean
  bytes: number
  available: boolean
}

interface Artifacts {
  version: string
  phone: PlatformArtifact
  tv: PlatformArtifact
  desktop: PlatformArtifact
}

// Generated by `npm run artifacts`; typed here because the JSON shape changes
// when a platform has no local file yet.
const artifacts = artifactsJson as Artifacts

export type Platform = 'phone' | 'tv' | 'desktop'

export interface ReleaseArtifact {
  /** Key used by the download page's platform switch. */
  platform: Platform
  name: string
  /** Short platform name for buttons and cards. */
  label: string
  /** What the file is, e.g. "Android 7.0+" or "Windows 10/11". */
  requirement: string
  file: string
  /** 0 when the installer for this platform is not in public/downloads yet. */
  bytes: number
  sizeLabel: string
  /** QR code that opens this platform's section of the download page. */
  qr: string
  /** True when the file lives on another host (a release asset). */
  external?: boolean
}

function size(bytes: number): string {
  if (!bytes) return '—'
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

export const VERSION = artifacts.version

export const RELEASES: ReleaseArtifact[] = [
  {
    platform: 'phone',
    name: `vntera-${VERSION}.apk`,
    label: 'Android phone',
    requirement: 'Android 7.0+',
    file: artifacts.phone.file,
    bytes: artifacts.phone.bytes,
    sizeLabel: size(artifacts.phone.bytes),
    qr: '/media/qr-phone.png',
  },
  {
    platform: 'tv',
    name: `vntera-tv-${VERSION}.apk`,
    label: 'Android TV',
    requirement: 'Android TV 7.0+',
    file: artifacts.tv.file,
    bytes: artifacts.tv.bytes,
    sizeLabel: size(artifacts.tv.bytes),
    qr: '/media/qr-tv.png',
  },
  {
    platform: 'desktop',
    name: `Vntera-Setup-${VERSION}.exe`,
    label: 'Windows',
    requirement: 'Windows 10 / 11 · 64-bit',
    // The site serves the installer from /downloads when it is staged there;
    // otherwise it falls back to the release asset, which is the only copy a
    // plain git deploy can carry.
    file: artifacts.desktop.selfHosted ? artifacts.desktop.file : artifacts.desktop.url || artifacts.desktop.file,
    bytes: artifacts.desktop.bytes,
    sizeLabel: size(artifacts.desktop.bytes),
    qr: '/media/qr-desktop.png',
  },
]

export function release(platform: Platform): ReleaseArtifact {
  return RELEASES.find((entry) => entry.platform === platform) ?? RELEASES[0]
}

/** Version baked into the current release installers (kept in step with package.json). */
export const ANDROID_RELEASE = {
  version: VERSION,
  // Served from /downloads/ so the SPA route /download is not shadowed by a real directory.
  file: release('phone').file,
  minAndroid: '7.0',
  sizeLabel: release('phone').sizeLabel,
} as const
